import { existsSync } from 'fs';
import { dirname, resolve } from 'path';
import { fileURLToPath } from 'url';

import type { StorybookConfig } from '@storybook/react-vite';

/**
 * This function is used to resolve the absolute path of a package.
 * It is needed in projects that use Yarn PnP or are set up within a monorepo.
 */
function getAbsolutePath(value: string) {
  return dirname(fileURLToPath(import.meta.resolve(`${value}/package.json`)));
}

/**
 * llms.txt, llms-full.txt and llms/*.md, generated by the polpo build (packages/polpo/ai/generate.ts).
 * They are served at the root of the site, e.g. https://ui.juanmsl.com/llms.txt
 */
const llmsDir = resolve(dirname(fileURLToPath(import.meta.url)), '../../../packages/polpo/dist/ai/web');

const config: StorybookConfig = {
  stories: [
    '../src/**/*.mdx',
    {
      directory: '../src/stories/components',
      titlePrefix: 'Components',
      files: '**/*.@(mdx|stories.@(mdx|js|jsx|mjs|ts|tsx))',
    },
  ],

  addons: [
    getAbsolutePath('@storybook/addon-a11y'),
    getAbsolutePath('@storybook/addon-docs'),
    getAbsolutePath('@storybook/addon-onboarding'),
  ],

  staticDirs: existsSync(llmsDir) ? [{ from: llmsDir, to: '/' }] : [],

  framework: {
    name: getAbsolutePath('@storybook/react-vite'),
    options: {},
  },

  features: {
    actions: false,
  },
};

export default config;
